-- Read-only verification after applying preview runtime grants.
-- Every returned row should have ok=true; no credentials or user records.
SELECT check_name,ok FROM (VALUES
 ('player role is NOLOGIN', (SELECT NOT rolcanlogin AND NOT rolsuper AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolbypassrls FROM pg_roles WHERE rolname='pileheads_player_runtime_access')),
 ('room role is NOLOGIN', (SELECT NOT rolcanlogin AND NOT rolsuper AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolbypassrls FROM pg_roles WHERE rolname='pileheads_runtime_access')),
 ('player can manage own-account service records',has_table_privilege('pileheads_player_runtime_access','public.pileheads_accounts','SELECT,INSERT,UPDATE,DELETE') AND has_table_privilege('pileheads_player_runtime_access','public.pileheads_account_sessions','SELECT,INSERT,UPDATE,DELETE')),
 ('player reads results and progression',has_table_privilege('pileheads_player_runtime_access','public.pileheads_player_rounds','SELECT') AND has_table_privilege('pileheads_player_runtime_access','public.pileheads_round_receipts','SELECT') AND has_table_privilege('pileheads_player_runtime_access','public.pileheads_player_progression','SELECT')),
 ('player cannot modify results',NOT has_table_privilege('pileheads_player_runtime_access','public.pileheads_round_receipts','INSERT,UPDATE,DELETE') AND NOT has_table_privilege('pileheads_player_runtime_access','public.pileheads_player_progression','INSERT,UPDATE,DELETE') AND NOT has_table_privilege('pileheads_player_runtime_access','public.pileheads_player_rounds','INSERT,UPDATE,DELETE')),
 ('player cannot read hidden room state',NOT has_any_column_privilege('pileheads_player_runtime_access','public.pilehead_rooms','SELECT')),
 ('player cannot write queue',NOT has_table_privilege('pileheads_player_runtime_access','public.pileheads_queue_tickets','INSERT,UPDATE,DELETE')),
 ('room can authenticate account digest',has_column_privilege('pileheads_runtime_access','public.pileheads_account_sessions','token_hash','SELECT') AND has_column_privilege('pileheads_runtime_access','public.pileheads_account_sessions','account_id','SELECT') AND has_column_privilege('pileheads_runtime_access','public.pileheads_account_sessions','expires_at','SELECT')),
 ('room cannot mutate sessions or read provider subjects',NOT has_table_privilege('pileheads_runtime_access','public.pileheads_account_sessions','INSERT,UPDATE,DELETE') AND NOT has_any_column_privilege('pileheads_runtime_access','public.pileheads_accounts','SELECT')),
 ('room can finalize results',has_table_privilege('pileheads_runtime_access','public.pileheads_round_receipts','INSERT') AND has_column_privilege('pileheads_runtime_access','public.pileheads_round_receipts','room_instance_id','SELECT') AND has_table_privilege('pileheads_runtime_access','public.pileheads_player_rounds','INSERT') AND has_column_privilege('pileheads_runtime_access','public.pileheads_player_rounds','account_id','SELECT')),
 ('room cannot delete or rewrite results',NOT has_table_privilege('pileheads_runtime_access','public.pileheads_round_receipts','UPDATE,DELETE') AND NOT has_table_privilege('pileheads_runtime_access','public.pileheads_player_rounds','UPDATE,DELETE')),
 ('room can award progression and operate queue',has_table_privilege('pileheads_runtime_access','public.pileheads_player_progression','SELECT,INSERT,UPDATE') AND has_table_privilege('pileheads_runtime_access','public.pileheads_queue_tickets','SELECT,INSERT,UPDATE,DELETE') AND has_table_privilege('pileheads_runtime_access','public.pileheads_match_offers','SELECT,INSERT,UPDATE,DELETE')),
 ('room cannot write moderation blocks',NOT has_table_privilege('pileheads_runtime_access','public.pileheads_match_blocks','INSERT,UPDATE,DELETE')),
 ('player cannot delete quota records',NOT has_table_privilege('pileheads_player_runtime_access','public.pileheads_profile_quota','DELETE'))
) checks(check_name,ok) ORDER BY check_name;
